int main() {
    int n;
    char grid[MAX_N][MAX_N + 1];
    scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        scanf("%s", grid[i]);
    }

    bool col_used[MAX_N] = {false};
    char result[MAX_N + 1];
    result[n] = '\0';

    for (int i = 0; i < n; i++) {
        char best_char = 'z' + 1;
        int best_col = -1;

        for (int j = 0; j < n; j++) {
            if (!col_used[j]) {
                if (grid[i][j] < best_char) {
                    // Check if picking this column leaves a valid selection for remaining rows
                    bool possible = true;
                    bool temp_col_used[MAX_N];
                    memcpy(temp_col_used, col_used, sizeof(col_used));
                    temp_col_used[j] = true;

                    for (int r = i + 1; r < n; r++) {
