int N;
char grid[20][21];
char best[21];
char current[21];
int used_col[20];

void solve(int row) {
    if (row == N) {
        current[N] = '\0';
        if (best[0] == '\0' || strcmp(current, best) < 0) {
            strcpy(best, current);
        }
        return;
    }
    // Find minimum character available in this row
    char min_char = 127;
    for (int j = 0; j < N; j++) {
        if (!used_col[j] && grid[row][j] < min_char) {
            min_char = grid[row][j];
        }
    }
    // Only try columns with min_char (pruning)
    // But if current > best already, prune
    for (int j = 0; j < N; j++) {
        if (!used_col[j] && grid[row][j] == min_char) {
            current[row] = grid[row][j];
            // Prune if current prefix already worse than best
            if (best[0] != '\0') {
                int cmp = strncmp(current, best, row + 1);
                if (cmp > 0) continue;
            }
            used_col[j] = 1;
            solve(row + 1);
            used_col[j] = 0;
        }
    }
}

