#define MAXN 205

static int N;
static char a[MAXN][MAXN + 5];
static int seen[MAXN], vis_id;
static int matchR[MAXN];

/* Kuhn DFS: can left node u be matched using allowed edges? */
int dfs(int u, int allowed[MAXN][MAXN]) {
    if (seen[u] == vis_id) return 0;
    seen[u] = vis_id;
    for (int v = 0; v < N; v++) {
        if (!allowed[u][v]) continue;
        if (matchR[v] == -1 || dfs(matchR[v], allowed)) {
            matchR[v] = u;
            return 1;
        }
    }
    return 0;
}

/* Check if perfect matching exists in current allowed graph */
int perfect_matching_exists(int allowed[MAXN][MAXN]) {
    for (int j = 0; j < N; j++) matchR[j] = -1;
    for (int i = 0; i < N; i++) {
        vis_id++;
        if (!dfs(i, allowed)) return 0;
    }
    return 1;
}

int main(void) {
    if (scanf("%d", &N) != 1) return 0;
    for (int i = 0; i < N; i++) {
        scanf("%s", a[i]);
    }

    static int base[MAXN][MAXN];
    static int test[MAXN][MAXN];
    static int chosenRow[MAXN], chosenCol[MAXN];
    static char ans[MAXN + 1];

    for (int i = 0; i < N; i++) {
        chosenRow[i] = 0;
        chosenCol[i] = 0;
        for (int j = 0; j < N; j++) base[i][j] = 1;
    }

    for (int pos = 0; pos < N; pos++) {
        char best = 127;

        for (int i = 0; i < N; i++) if (!chosenRow[i]) {
            for (int j = 0; j < N; j++) if (!chosenCol[j]) {
                if (a[i][j] < best) {
                    /* Build graph requiring current pick (i,j),
                       previous picks already fixed in base,
                       and all future picks unrestricted among remaining rows/cols. */
                    for (int r = 0; r < N; r++) {
                        for (int c = 0; c < N; c++) test[r][c] = 0;
                    }

                    /* previous fixed choices */
                    for (int r = 0; r < N; r++) {
                        if (chosenRow[r]) {
                            for (int c = 0; c < N; c++) {
                                if (base[r][c]) test[r][c] = 1;
                            }
                        }
                    }

                    /* current forced choice */
                    test[i][j] = 1;

                    /* remaining free rows/cols */
                    for (int r = 0; r < N; r++) {
                        if (chosenRow[r] || r == i) continue;
                        for (int c = 0; c < N; c++) {
                            if (chosenCol[c] || c == j) continue;
                            test[r][c] = 1;
                        }
                    }

                    if (perfect_matching_exists(test)) {
                        best = a[i][j];
                    }
                }
            }
        }

        /* choose lexicographically smallest feasible character,
           then among all such cells, find one that keeps feasibility */
        int bi = -1, bj = -1;
        for (int i = 0; i < N && bi == -1; i++) if (!chosenRow[i]) {
            for (int j = 0; j < N; j++) if (!chosenCol[j] && a[i][j] == best) {
                for (int r = 0; r < N; r++) {
                    for (int c = 0; c < N; c++) test[r][c] = 0;
                }

                for (int r = 0; r < N; r++) {
                    if (chosenRow[r]) {
                        for (int c = 0; c < N; c++) {
                            if (base[r][c]) test[r][c] = 1;
                        }
                    }
                }

                test[i][j] = 1;

                for (int r = 0; r < N; r++) {
                    if (chosenRow[r] || r == i) continue;
                    for (int c = 0; c < N; c++) {
                        if (chosenCol[c] || c == j) continue;
                        test[r][c] = 1;
                    }
                }

                if (perfect_matching_exists(test)) {
                    bi = i;
                    bj = j;
                    break;
                }
            }
        }

        ans[pos] = best;
        chosenRow[bi] = 1;
        chosenCol[bj] = 1;

        for (int c = 0; c < N; c++) base[bi][c] = 0;
        base[bi][bj] = 1;
    }

    ans[N] = '\0';
    printf("%s\n", ans);
    return 0;
}

