bool canMatch(vector<bool>& rowActive, vector<bool>& colActive) {
    fill(matchL, matchL + N, -1);
    fill(matchR, matchR + N, -1);
    int matched = 0;
    for (int u = 0; u < N; u++) {
        if (!rowActive[u]) continue;
        fill(used, used + N, false);
        if (dfs(u, rowActive, colActive)) matched++;
    }
    int need = 0;
    for (int i = 0; i < N; i++) if (rowActive[i]) need++;
    return matched == need;
}

