using namespace std;

bool canComplete(const vector<string>& a, const vector<int>& rows, const vector<int>& cols, char limitChar) {
    int n = (int)rows.size();
    vector<vector<int>> g(n);
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (a[rows[i]][cols[j]] <= limitChar) g[i].push_back(j);
        }
    }

    vector<int> matchR(n, -1);

    function<bool(int, vector<int>&)> dfs = [&](int u, vector<int>& vis) -> bool {
        for (int v : g[u]) {
            if (vis[v]) continue;
            vis[v] = 1;
            if (matchR[v] == -1 || dfs(matchR[v], vis)) {
                matchR[v] = u;
                return true;
            }
        }
        return false;
    };

    int matched = 0;
    for (int i = 0; i < n; ++i) {
        vector<int> vis(n, 0);
        if (dfs(i, vis)) ++matched;
    }
    return matched == n;
}

