def max_matching(graph, rows, cols):
    # graph[r] = set of available columns
    match_col = {}
    match_row = {}

    def dfs(r, visited):
        for c in graph[r]:
            if c not in visited:
                visited.add(c)
                if c not in match_col or dfs(match_col[c], visited):
                    match_col[c] = r
                    match_row[r] = c
                    return True
        return False

    count = 0
    for r in rows:
        visited = set()
        if dfs(r, visited):
            count += 1
    return count, match_col, match_row

