public class DecodeMessage {
    static int n;
    static char[][] grid;
    static boolean[] usedCol;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        sc.nextLine();
        grid = new char[n][n];
        for (int i = 0; i < n; i++) {
            String line = sc.nextLine();
            for (int j = 0; j < n; j++) {
                grid[i][j] = line.charAt(j);
            }
        }
        sc.close();

        usedCol = new boolean[n];
        StringBuilder result = new StringBuilder();

        for (int row = 0; row < n; row++) {
            // Try columns in sorted order of characters
            List<int[]> candidates = new ArrayList<>();
            for (int col = 0; col < n; col++) {
                if (!usedCol[col]) {
                    candidates.add(new int[]{col, grid[row][col]});
                }
            }
            // Sort by character value, then column index for tie-breaking
            candidates.sort((a, b) -> {
                if (a[1] != b[1]) return a[1] - b[1];
                return a[0] - b[0];
            });

            for (int[] cand : candidates) {
                int col = cand[0];
                usedCol[col] = true;
                if (canMatch(row + 1)) {
                    result.append((char) cand[1]);
                    break;
                }
                usedCol[col] = false;
            }
        }
        System.out.println(result.toString());
    }

    // Check if we can match remaining rows to unused columns
    static boolean canMatch(int startRow) {
        if (startRow >= n) return true;
        boolean[] seenCol = new boolean[n];
        int[] matchRowToCol = new int[n];
        Arrays.fill(matchRowToCol, -1);
        int matchCount = 0;

        for (int r = startRow; r < n; r++) {
            Arrays.fill(seenCol, false);
            if (dfs(r, seenCol, matchRowToCol)) {
                matchCount++;
            }
        }
        return matchCount == (n - startRow);
    }

    static boolean dfs(int r, boolean[] seenCol, int[] matchRowToCol) {
        for (int c = 0; c < n; c++) {
            if (!usedCol[c] && !seenCol[c]) {
                seenCol[c] = true;
                if (matchRowToCol[c] == -1 || dfs(matchRowToCol[c], seenCol, matchRowToCol)) {
                    matchRowToCol[c] = r;
                    return true;
                }
            }
        }
        return false;
    }
}

