import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c != -1 && Character.isWhitespace(c));
            if (c == -1) return null;
            while (c != -1 && !Character.isWhitespace(c)) {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    static int N;
    static char[][] a;

    // Kuhn matching: can we match all remaining rows [rowStart..N-1]
    // using only columns with colAvailable[c] = true
    // and only edges with character <= limit?
    static boolean canMatchWithLimit(int rowStart, boolean[] colAvailable, char limit) {
        int rows = N - rowStart;
        int[] matchToCol = new int[N];
        Arrays.fill(matchToCol, -1);

        for (int r = rowStart; r < N; r++) {
            boolean[] vis = new boolean[N];
            if (!dfs(r, rowStart, colAvailable, limit, matchToCol, vis)) {
                return false;
            }
        }
        return true;
    }

    static boolean dfs(int r, int rowStart, boolean[] colAvailable, char limit, int[] matchToCol, boolean[] vis) {
        for (int c = 0; c < N; c++) {
            if (!colAvailable[c] || vis[c] || a[r][c] > limit) continue;
            vis[c] = true;
            if (matchToCol[c] == -1 || dfs(matchToCol[c], rowStart, colAvailable, limit, matchToCol, vis)) {
                matchToCol[c] = r;
                return true;
            }
        }
        return false;
    }

    // Perfect matching among remaining rows/columns with exact chosen character on current row
    static boolean canCompleteAfterChoosing(int currentRow, int chosenCol, char chosenChar, boolean[] usedCols) {
        boolean[] colAvailable = new boolean[N];
        for (int c = 0; c < N; c++) colAvailable[c] = !usedCols[c];
        colAvailable[chosenCol] = false;

        int[] matchToCol = new int[N];
        Arrays.fill(matchToCol, -1);

        for (int r = currentRow + 1; r < N; r++) {
            boolean[] vis = new boolean[N];
            if (!dfsAny(r, colAvailable, matchToCol, vis)) return false;
        }
        return true;
    }

    static boolean dfsAny(int r, boolean[] colAvailable, int[] matchToCol, boolean[] vis) {
        for (int c = 0; c < N; c++) {
            if (!colAvailable[c] || vis[c]) continue;
            vis[c] = true;
            if (matchToCol[c] == -1 || dfsAny(matchToCol[c], colAvailable, matchToCol, vis)) {
                matchToCol[c] = r;
                return true;
            }
        }
        return false;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        String first = fs.next();
        if (first == null) return;

        N = Integer.parseInt(first);
        a = new char[N][N];

        for (int i = 0; i < N; i++) {
            String s = fs.next();
            while (s.length() < N) s += fs.next();
            a[i] = s.toCharArray();
        }

        boolean[] usedCols = new boolean[N];
        StringBuilder ans = new StringBuilder();

        for (int r = 0; r < N; r++) {
            char best = Character.MAX_VALUE;
            int bestCol = -1;

            for (char ch = 0; ch <= 255; ch++) {
                boolean found = false;

                for (int c = 0; c < N; c++) {
                    if (usedCols[c]) continue;
                    if (a[r][c] != ch) continue;

                    if (canCompleteAfterChoosing(r, c, ch, usedCols)) {
                        best = ch;
                        bestCol = c;
                        found = true;
                        break;
                    }
                }

                if (found) break;
            }

            usedCols[bestCol] = true;
            ans.append(best);
        }

        System.out.print(ans.toString());
    }
}
